def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    n = next(k for k in range(1, 31) if k * k + k - 1 == h)
    out = [[0 if v == 3 else v for v in row] for row in g]

    # Locate the band of 3s, which hides one tile row or tile column.
    hidden_row = None
    hidden_col = None
    for tr in range(n):
        r0 = tr * (n + 1)
        if all(g[r][c] == 3 for r in range(r0, r0 + n) for c in range(w)):
            hidden_row = tr
    for tc in range(n):
        c0 = tc * (n + 1)
        if all(g[r][c] == 3 for r in range(h) for c in range(c0, c0 + n)):
            hidden_col = tc

    def get_tile(tr, tc):
        r0, c0 = tr * (n + 1), tc * (n + 1)
        return [g[r0 + i][c0:c0 + n] for i in range(n)]

    def put_tile(tr, tc, tile):
        r0, c0 = tr * (n + 1), tc * (n + 1)
        for i in range(n):
            for j in range(n):
                out[r0 + i][c0 + j] = tile[i][j]

    # Fill a hidden tile by copying the nearest matching tile along its row/column.
    if hidden_row is not None:
        for tc in range(n):
            candidates = []
            for tr in range(n):
                if tr == hidden_row:
                    continue
                tile = get_tile(tr, tc)
                if any(v != 0 for row in tile for v in row):
                    candidates.append((abs(tr - hidden_row), tile))
            for _, tile in sorted(candidates, key=lambda x: x[0]):
                if tile[hidden_row][tc] == 2:
                    put_tile(hidden_row, tc, tile)
                    break

    elif hidden_col is not None:
        for tr in range(n):
            candidates = []
            for tc in range(n):
                if tc == hidden_col:
                    continue
                tile = get_tile(tr, tc)
                if any(v != 0 for row in tile for v in row):
                    candidates.append((abs(tc - hidden_col), tile))
            for _, tile in sorted(candidates, key=lambda x: x[0]):
                if tile[tr][hidden_col] == 2:
                    put_tile(tr, hidden_col, tile)
                    break

    # Mark each tile's cell at its tile-grid coordinate.
    for tr in range(n):
        for tc in range(n):
            r, c = tr * (n + 1) + tr, tc * (n + 1) + tc
            if out[r][c] == 2:
                out[r][c] = 8

    return out
